using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using System.ComponentModel;
using System.Text.Json;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research agent. Given a topic, use the WebSearch tool to find relevant information, "
    + "then use the AddNote tool to record key findings. Search multiple times to gather comprehensive "
    + "information. After researching, use GetNotes to review what you've collected, then provide a "
    + "final summary to the user.")
{
    Tools =
    [
        AIFunctionFactory.Create(
            ([Description("The search query")] string query) =>
            {
                Console.WriteLine($"  [Searching] \"{query}\"");
                // Simulated web search results
                return JsonSerializer.Serialize(SimulatedSearch.Search(query));
            },
            "WebSearch",
            "Searches the web for information on a topic. Returns a list of results with titles and snippets."),

        AIFunctionFactory.Create(
            ([Description("A concise note summarizing a finding")] string note,
             [Description("The source URL or description")] string source) =>
            {
                notes.Add(note, source);
                Console.WriteLine($"  [Note added] {note[..Math.Min(note.Length, 60)]}...");
                return "Note saved successfully.";
            },
            "AddNote",
            "Records a research finding with its source for later summarization."),

        AIFunctionFactory.Create(
            () =>
            {
                var allNotes = notes.GetAll();
                return allNotes.Count == 0
                    ? "No notes recorded yet."
                    : JsonSerializer.Serialize(allNotes);
            },
            "GetNotes",
            "Retrieves all recorded research notes to review before summarizing."),
    ],
};

var topic = args.Length > 0 ? string.Join(' ', args) : "the impact of quantum computing on cryptography";

Console.WriteLine($"Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly. Search for multiple aspects, take notes on key findings, "
        + $"then provide a comprehensive summary.\n\nTopic: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes Collected ---");
foreach (var n in notes.GetAll())
{
    Console.WriteLine($"• {n.Note} (Source: {n.Source})");
}

// --- Supporting types ---

public class ResearchNotes
{
    private readonly List<NoteEntry> _notes = [];

    public void Add(string note, string source) => _notes.Add(new(note, source));
    public List<NoteEntry> GetAll() => [.. _notes];
}

public record NoteEntry(string Note, string Source);

public static class SimulatedSearch
{
    private static readonly Dictionary<string, List<SearchResult>> _cache = new(StringComparer.OrdinalIgnoreCase);

    public static List<SearchResult> Search(string query)
    {
        var q = query.ToLowerInvariant();
        return
        [
            new($"Research findings on: {query}",
                $"https://research.example.com/{Uri.EscapeDataString(q)}",
                $"Recent studies show significant developments in {query}. Experts suggest this area will see major advances in the coming years."),
            new($"{query} - Latest Developments",
                $"https://news.example.com/{Uri.EscapeDataString(q)}",
                $"Industry leaders are investing heavily in {query}. Key breakthroughs include improved methodologies and wider adoption across sectors."),
            new($"Understanding {query}: A Comprehensive Guide",
                $"https://guide.example.com/{Uri.EscapeDataString(q)}",
                $"The fundamentals of {query} involve several core concepts. This guide covers the basics, current state of the art, and future directions."),
        ];
    }
}

public record SearchResult(string Title, string Url, string Snippet);

